"""Phone-readable summary of the two source detector gates."""
import argparse,json
from pathlib import Path
H=Path(__file__).resolve().parent
def make():
    r=json.loads((H/'results.json').read_text(encoding='utf8'))
    a=r['summary']['test8_top']['match_fraction'];a_null=sorted(z['test8_top']['match_fraction'] for z in r['null_maxima'])[24]
    b=r['summary']['test9_flagged_pages'];b_null=sorted(z['test9_flag_count'] for z in r['null_maxima'])[24]
    return f'''<svg xmlns="http://www.w3.org/2000/svg" width="320" height="354" viewBox="0 0 320 354" font-family="Arial, sans-serif" role="img" aria-labelledby="title desc"><title id="title">Two source period screens compared with complete shuffled searches</title><desc id="desc">Test8's highest manuscript key-repeat fraction was {a:.1%}, below the greater-than-25-percent report line, and 12 of 49 full shuffled searches reached it. Test9 flagged {b} of 34 manuscript pages, versus {b_null} at the middle of 49 shuffled searches. Both detectors found a planted period13 on the appropriate page.</desc><rect width="320" height="354" fill="#fff"/><text x="12" y="25" font-size="17" font-weight="bold" fill="#172f3d">Period checks</text><text x="12" y="53" font-size="14" fill="#3e515b">Check 8 · Key-lag matches</text><text x="12" y="86" font-size="14">LP2 highest</text><rect x="139" y="67" width="{a*500:.1f}" height="21" fill="#2c6881"/><text x="303" y="84" text-anchor="end" font-size="14">{a:.0%}</text><text x="12" y="119" font-size="14">Shuffle middle</text><rect x="139" y="100" width="{a_null*500:.1f}" height="21" fill="#91a3ad"/><text x="303" y="117" text-anchor="end" font-size="14">{a_null:.0%}</text><line x1="264" y1="64" x2="264" y2="124" stroke="#a64242" stroke-width="2" stroke-dasharray="4 3"/><text x="12" y="147" font-size="13" fill="#4b5d66">Report only above 25% · LP2: no hits</text><line x1="12" y1="164" x2="308" y2="164" stroke="#c8d2d6"/><text x="12" y="191" font-size="14" fill="#3e515b">Check 9 · Column-score flags</text><text x="12" y="224" font-size="14">LP2 pages</text><rect x="139" y="205" width="{b*3.2:.1f}" height="21" fill="#2c6881"/><text x="303" y="222" text-anchor="end" font-size="14">{b}/34</text><text x="12" y="257" font-size="14">Shuffle middle</text><rect x="139" y="238" width="{b_null*3.2:.1f}" height="21" fill="#91a3ad"/><text x="303" y="255" text-anchor="end" font-size="14">{b_null}/34</text><text x="12" y="295" font-size="14" fill="#243b46">Both checks found a planted period 13.</text><text x="12" y="320" font-size="13" fill="#4b5d66">49 shared full-search shuffles; source rules.</text><text x="12" y="341" font-size="12" fill="#586970">A flagged page is not a decipherment.</text></svg>\n'''
if __name__=='__main__':
    ap=argparse.ArgumentParser();ap.add_argument('--check',action='store_true');a=ap.parse_args();p=H/'comparison.svg';s=make()
    if a.check:assert p.read_text(encoding='utf8')==s;print('PASS SVG')
    else:p.write_text(s,encoding='utf8',newline='\n')
